#!/usr/bin/env bash
# Remove everything the pipelines generate: the PostGIS container, network and
# volume (all parta/partb tables), and the generated files under data/.
#
# The inputs are kept: data/osm/ (the OSM extract) and data/porto_taxi/.
#
# Usage: ./cleanup.sh [-y|--yes] [-n|--dry-run]
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$ROOT"

# Generated by part_a (porto.csv) and part_b (features, CV folds, results, figures).
GENERATED=(data/generated data/entrance_tagging)
LOCK_FILE=data/entrance_tagging/.pipeline.lock

assume_yes=false
dry_run=false
for arg in "$@"; do
  case "$arg" in
    -y | --yes) assume_yes=true ;;
    -n | --dry-run) dry_run=true ;;
    -h | --help)
      sed -n '2,7p' "$0" | sed 's/^# \{0,1\}//'
      exit 0
      ;;
    *)
      echo "error: unknown option $arg (see --help)" >&2
      exit 2
      ;;
  esac
done

run() {
  if $dry_run; then
    echo "[dry run] $*"
  else
    "$@"
  fi
}

# A running Part B pipeline holds this lock (see part_b/run_pipeline.py).
if [[ -f "$LOCK_FILE" ]] && ! flock -n "$LOCK_FILE" true; then
  echo "error: a Part B pipeline is running (pid $(cat "$LOCK_FILE")); wait for it to finish" >&2
  exit 1
fi

# Everything inside the generated directories, dotfiles included; the directories stay.
mapfile -t files < <(find "${GENERATED[@]}" -mindepth 1 -maxdepth 1 2>/dev/null | sort)

echo "This removes:"
echo "  - the Docker Compose containers, network and volumes (all PostGIS data)"
if ((${#files[@]})); then
  printf '  - %s\n' "${files[@]}"
else
  echo "  - no generated files (already clean)"
fi
echo "It keeps data/osm/ and data/porto_taxi/."

if ! $assume_yes && ! $dry_run; then
  read -r -p "Continue? [y/N] " answer
  [[ "$answer" =~ ^[Yy]$ ]] || { echo "Aborted."; exit 1; }
fi

run docker compose down --volumes --remove-orphans
if ((${#files[@]})); then
  run rm -rf -- "${files[@]}"
fi
if $dry_run; then
  echo "Dry run: nothing was removed."
else
  echo "Clean. Run the pipelines again to regenerate everything."
fi
